INSERT INTO "core_herobanner" VALUES(1,'Royal Bridal Trousseau Collection 2026','Handcrafted in 22K Hallmarked Gold, Uncut Polki Diamonds & Basra Pearls','EXCLUSIVE BRIDAL COUTURE','Explore Royal Wedding Sets','/products/?category=bridal-trousseau','',1,1);
INSERT INTO "core_herobanner" VALUES(2,'Certified Solitaire Diamond Rings','GIA & IGI Authenticated Triple Excellent Cut Solitaires in 18K Gold & Platinum','ETERNAL ROMANCE','View Solitaire Collection','/products/?category=diamond-solitaires','',2,1);
INSERT INTO "core_herobanner" VALUES(3,'Bespoke Custom Jewellery Studio','Transform your vision into handcrafted gold reality with 3D CAD design & artisan quotes','CUSTOM DESIGN SERVICE','Design Your Jewellery','/custom-jewellery/','',3,1);
INSERT INTO "core_testimonial" VALUES(1,'Pooja & Rohan Mehra','Mumbai, Maharashtra',5,'Our wedding jewellery was perfection!','We ordered our entire bridal choker and kada set from Aura Gold. The 360-degree view helped us inspect every angle before ordering. The hallmarking and certificate gave us total peace of mind.','',1,'2026-11-10 03:33:22.996499');
INSERT INTO "core_testimonial" VALUES(2,'Dr. Vikramaditya Rao','Hyderabad, Telangana',5,'Bespoke Diamond Solitaire for proposal','I uploaded a custom design sketch with reference photos on their Custom Jewellery module. Within 24 hours, their artisan sent a detailed quotation and 3D CAD render. She said YES!','',1,'2026-11-10 03:33:23.001498');
INSERT INTO "core_testimonial" VALUES(3,'Sunita Singhania','New Delhi',5,'Authentic 24K Bullion & Transparent Pricing','Transparent breakdown of gold rates, making charges, and GST. No hidden costs. Insured tamper-proof delivery arrived in 48 hours.','',1,'2026-11-10 03:33:23.006504');
INSERT INTO "custom_orders_customorder" VALUES(1,'CUST-202611-DEMO1','Ananya Sharma','customer@gmail.com','+91 98765 43210','RING','YELLOW_GOLD','18K',7.5,95000,'US 6.5 / Indian 13','','Victorian style vintage halo ring with an oval Colombian emerald in center, surrounded by round brilliant diamond halo and milgrain filigree engraving on band.','Inside band engraving: "Forever & Always 14.02.2026"',NULL,'QUOTATION_SENT','CAD model prepared. 18K yellow gold casting scheduled upon customer approval.','2026-11-10 03:33:23.012339','2026-11-10 03:33:23.012339',2);
