INSERT INTO "products_product" VALUES(1,'Royal Maharani 22K Kundan Choker Necklace','royal-maharani-22k-kundan-choker-necklace','NK-GLD-916-001','Breathtaking bridal necklace handcrafted by Jaipur master artisans. Features uncut Polki stones encrusted in 22K hallmarked gold with natural Zambian emerald drops and south sea pearl tassels.','BIS Hallmarked 916. Length: 16 inches with adjustable gold dori. Certificate: IGI Authenticated. Lock: Traditional royal screw clasp.','GOLD','22K',48.65,42.1,6.55,14500,342000,8,3,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',1,1,1,1,'2026-11-10 03:33:21.923399','2026-11-10 03:33:21.923399',3,10);
INSERT INTO "products_product" VALUES(2,'Eternal Brilliance 1.5ct Solitaire Diamond Ring','eternal-brilliance-15ct-solitaire-diamond-ring','RG-DIA-750-002','A timeless solitaire engagement ring featuring a GIA certified 1.50-carat round brilliant cut diamond of VVS1 clarity and E colorless grade, mounted on an 18K white gold cathedral band.','Metal: 18K White Gold (Hallmarked 750). Diamond: 1.50 Ct, Triple Excellent Cut. Setting: 6-prong platinum claw mount. Ring Size: Indian 14 (resizing available).','DIAMOND','18K',6.2,5.9,1.5,8500,185000,10,5,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',1,1,0,1,'2026-11-10 03:33:22.243751','2026-11-10 03:33:22.243751',2,6);
INSERT INTO "products_product" VALUES(3,'Imperial Peacock 22K Gold Antique Jhumkas','imperial-peacock-22k-gold-antique-jhumkas','ER-GLD-916-003','Regal temple earrings showcasing dancing peacock motifs, intricate filigree domes, and hanging natural Basra pearl drops with vibrant Burmese ruby cabochons.','Gold: 22K Yellow Antique Finish. Length: 55mm. Width: 26mm. Weight: 24.80g. Lock: South Indian Bombay screw closure.','GOLD','22K',24.8,22.4,2.4,6800,178000,5,4,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',1,1,1,0,'2026-11-10 03:33:22.514376','2026-11-10 03:33:22.514376',4,15);
INSERT INTO "products_product" VALUES(4,'Heritage Lakshmi Antique 22K Gold Kada','heritage-lakshmi-antique-22k-gold-kada','BG-GLD-916-004','Handcrafted solid 22K gold kada featuring embossed Goddess Lakshmi motifs flanked by majestic elephants with floral nagas repousse carvings.','Hallmark: BIS 916. Size: 2.6 inches inner diameter (adjustable openable clasp). Finish: Antique Nakashi matte polish.','GOLD','22K',38.25,36.8,1.45,11200,275000,0,2,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',1,0,0,1,'2026-11-10 03:33:22.797443','2026-11-10 03:33:22.797443',1,4);
INSERT INTO "products_product" VALUES(5,'24K Pure Sovereign Lakshmi Gold Coin (10 Grams)','24k-pure-sovereign-lakshmi-gold-coin-10-grams','CN-GLD-999-005','999.9 pure 24K gold investment coin sealed in tamper-evident NABL-accredited security assay blister packaging with unique QR verification code.','Weight: 10.000 grams. Purity: 24 Karat (99.9% Pure). Diameter: 24mm. Obverse: Goddess Lakshmi. Reverse: Royal Monogram & Hallmark.','GOLD','24K',10,10,0,850,78500,0,25,'IN_STOCK','ACTIVE','UNISEX',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',0,1,0,1,'2026-11-10 03:33:22.836393','2026-11-10 03:33:22.836393',6,23);
INSERT INTO "products_product" VALUES(6,'Rose Gold Diamond Solitaire Tennis Bracelet','rose-gold-diamond-solitaire-tennis-bracelet','BR-DIA-750-006','A graceful continuum of 52 matching brilliant cut diamonds set in 18K warm rose gold prongs with dual safety box clasp.','Diamonds: 52 stones, total 2.60 carats, Color F-G, Clarity VS. Length: 7.0 inches. Metal: 18K Rose Gold (750).','ROSE_GOLD','18K',14.2,12.7,1.5,9500,210000,12,3,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',1,1,1,0,'2026-11-10 03:33:22.873704','2026-11-10 03:33:22.873704',2,8);
INSERT INTO "products_product" VALUES(7,'Temple Heritage Floral Kasu Mala Haram','temple-heritage-floral-kasu-mala-haram','NK-GLD-916-007','Traditional grand Kasumala necklace comprising 42 embossed coins depicting Lord Balaji and Goddess Padmavathi, culminating in a magnificent nakshi pendant.','Purity: 22K (916). Length: 24 inches long haram. Weight: 62.5g. Gemstones: Natural unheated ruby beads.','GOLD','22K',62.5,58.9,3.6,18000,435000,7,1,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',1,1,1,1,'2026-11-10 03:33:22.910404','2026-11-10 11:37:09.796442',4,14);
INSERT INTO "products_product" VALUES(8,'Celestial Starburst 18K Diamond Solitaire Pendant','celestial-starburst-18k-diamond-solitaire-pendant','PD-DIA-750-008','Dazzling starburst halo pendant featuring a center 0.40 ct solitaire enveloped in a sparkling diamond halo with an 18K yellow gold cable chain included.','Diamond Carat: 0.65 ctw. Chain: 18 inch adjustable gold chain. Certification: SGL International.','DIAMOND','18K',4.8,4.4,0.4,4500,62000,15,3,'IN_STOCK','ACTIVE','WOMEN',1,'BIS-916-IND','VVS-VS','E-F Colorless','Excellent Ideal Cut',0,1,1,1,'2026-11-10 03:33:22.946619','2026-11-10 11:36:14.706655',2,7);
