BEGIN TRANSACTION;
CREATE TABLE "accounts_address" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "address_type" varchar(20) NOT NULL, "full_name" varchar(150) NOT NULL, "phone" varchar(20) NOT NULL, "street_address" text NOT NULL, "landmark" varchar(150) NOT NULL, "city" varchar(100) NOT NULL, "state" varchar(100) NOT NULL, "pincode" varchar(10) NOT NULL, "country" varchar(100) NOT NULL, "is_default" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "message" text NOT NULL, "link" varchar(250) NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_userprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "phone" varchar(20) NOT NULL, "avatar" varchar(100) NULL, "date_of_birth" date NULL, "loyalty_points" integer unsigned NOT NULL CHECK ("loyalty_points" >= 0), "newsletter_opt_in" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_wishlist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_wishlistitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "added_at" datetime NOT NULL, "product_id" bigint NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED, "wishlist_id" bigint NOT NULL REFERENCES "accounts_wishlist" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cart_cart" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_key" varchar(40) NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cart_cartitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "cart_id" bigint NOT NULL REFERENCES "cart_cart" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_contactinquiry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "subject" varchar(250) NOT NULL, "message" text NOT NULL, "is_resolved" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "core_herobanner" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "subtitle" varchar(300) NOT NULL, "badge_text" varchar(50) NOT NULL, "button_text" varchar(50) NOT NULL, "button_url" varchar(200) NOT NULL, "image" varchar(100) NULL, "display_order" integer unsigned NOT NULL CHECK ("display_order" >= 0), "is_active" bool NOT NULL);
CREATE TABLE "core_subscriber" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar(254) NOT NULL UNIQUE, "subscribed_at" datetime NOT NULL, "is_active" bool NOT NULL);
CREATE TABLE "core_testimonial" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customer_name" varchar(150) NOT NULL, "city" varchar(100) NOT NULL, "rating" smallint unsigned NOT NULL CHECK ("rating" >= 0), "title" varchar(200) NOT NULL, "review_text" text NOT NULL, "avatar" varchar(100) NULL, "is_featured" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "custom_orders_customorder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "request_id" varchar(50) NOT NULL UNIQUE, "full_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "jewellery_type" varchar(30) NOT NULL, "metal_type" varchar(30) NOT NULL, "gold_purity" varchar(20) NOT NULL, "expected_weight" decimal NOT NULL, "preferred_budget" decimal NOT NULL, "ring_size" varchar(50) NOT NULL, "necklace_length" varchar(50) NOT NULL, "design_description" text NOT NULL, "special_instructions" text NOT NULL, "expected_delivery_date" date NULL, "status" varchar(30) NOT NULL, "admin_notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "custom_orders_customorderimage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "caption" varchar(150) NOT NULL, "uploaded_at" datetime NOT NULL, "custom_order_id" bigint NOT NULL REFERENCES "custom_orders_customorder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "custom_orders_customorderquotation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quotation_number" varchar(50) NOT NULL UNIQUE, "estimated_weight" decimal NOT NULL, "metal_rate_applied" decimal NOT NULL, "estimated_metal_cost" decimal NOT NULL, "making_charges" decimal NOT NULL, "stone_charges" decimal NOT NULL, "gst_amount" decimal NOT NULL, "total_estimated_price" decimal NOT NULL, "estimated_making_days" integer unsigned NOT NULL CHECK ("estimated_making_days" >= 0), "design_notes" text NOT NULL, "cad_design_file" varchar(100) NULL, "status" varchar(30) NOT NULL, "customer_feedback" text NOT NULL, "valid_until" date NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "custom_order_id" bigint NOT NULL REFERENCES "custom_orders_customorder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action_time" datetime NOT NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0));
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "orders_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order_number" varchar(50) NOT NULL UNIQUE, "invoice_number" varchar(60) NOT NULL UNIQUE, "customer_name" varchar(150) NOT NULL, "customer_email" varchar(254) NOT NULL, "customer_phone" varchar(20) NOT NULL, "shipping_address" text NOT NULL, "billing_address" text NOT NULL, "items_total" decimal NOT NULL, "making_charges_total" decimal NOT NULL, "discount_amount" decimal NOT NULL, "tax_amount" decimal NOT NULL, "shipping_charges" decimal NOT NULL, "grand_total" decimal NOT NULL, "payment_status" varchar(20) NOT NULL, "order_status" varchar(25) NOT NULL, "tracking_number" varchar(100) NOT NULL, "courier_partner" varchar(100) NOT NULL, "estimated_delivery" date NULL, "order_notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "payment_method" varchar(20) NOT NULL);
CREATE TABLE "orders_orderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_name" varchar(250) NOT NULL, "product_sku" varchar(50) NOT NULL, "metal_type" varchar(30) NOT NULL, "purity" varchar(30) NOT NULL, "gross_weight" decimal NOT NULL, "net_weight" decimal NOT NULL, "stone_weight" decimal NOT NULL, "unit_price" decimal NOT NULL, "making_charges" decimal NOT NULL, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "total_price" decimal NOT NULL, "order_id" bigint NOT NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "orders_payment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "payment_method" varchar(100) NOT NULL, "amount" decimal NOT NULL, "status" varchar(20) NOT NULL, "payment_details" text NOT NULL, "created_at" datetime NOT NULL, "order_id" bigint NOT NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "transaction_id" varchar(120) NOT NULL UNIQUE);
CREATE TABLE "products_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE, "slug" varchar(150) NOT NULL UNIQUE, "description" text NOT NULL, "image" varchar(100) NULL, "icon_class" varchar(50) NOT NULL, "is_featured" bool NOT NULL, "is_active" bool NOT NULL, "display_order" integer unsigned NOT NULL CHECK ("display_order" >= 0));
CREATE TABLE "products_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(250) NOT NULL, "slug" varchar(280) NOT NULL UNIQUE, "sku" varchar(50) NOT NULL UNIQUE, "description" text NOT NULL, "specifications" text NOT NULL, "metal_type" varchar(20) NOT NULL, "purity" varchar(20) NOT NULL, "gross_weight" decimal NOT NULL, "net_weight" decimal NOT NULL, "stone_weight" decimal NOT NULL, "making_charges" decimal NOT NULL, "base_price" decimal NOT NULL, "discount_percent" decimal NOT NULL, "stock" integer unsigned NOT NULL CHECK ("stock" >= 0), "availability" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "gender" varchar(15) NOT NULL, "hallmark_certified" bool NOT NULL, "certificate_number" varchar(100) NOT NULL, "diamond_clarity" varchar(50) NOT NULL, "diamond_color" varchar(50) NOT NULL, "diamond_cut" varchar(50) NOT NULL, "is_featured" bool NOT NULL, "is_trending" bool NOT NULL, "is_new" bool NOT NULL, "is_bestseller" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "products_category" ("id") DEFERRABLE INITIALLY DEFERRED, "subcategory_id" bigint NULL REFERENCES "products_subcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_product360image" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "frame_number" integer unsigned NOT NULL CHECK ("frame_number" >= 0), "created_at" datetime NOT NULL, "product_id" bigint NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_productimage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "is_primary" bool NOT NULL, "alt_text" varchar(200) NOT NULL, "sort_order" integer unsigned NOT NULL CHECK ("sort_order" >= 0), "product_id" bigint NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_review" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rating" smallint unsigned NOT NULL CHECK ("rating" >= 0), "title" varchar(150) NOT NULL, "comment" text NOT NULL, "is_verified_purchase" bool NOT NULL, "is_approved" bool NOT NULL, "created_at" datetime NOT NULL, "product_id" bigint NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_subcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "slug" varchar(150) NOT NULL, "description" text NOT NULL, "is_active" bool NOT NULL, "category_id" bigint NOT NULL REFERENCES "products_category" ("id") DEFERRABLE INITIALLY DEFERRED);
